{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Integrative & Whole-Person Care</title>
  <meta name="description" content="Personalized holistic care combining nutrition, lifestyle, mindfulness, and targeted testing. Education-first, no guaranteed cures.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="split-diagonal">
  <header class="site-header">
    <div class="brand">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <small class="tag">{{TAGLINE}}</small>
    </div>
    <nav class="main-nav">
      <button id="nav-toggle" aria-expanded="false">☰</button>
      <ul id="nav-list">
        <li><a href="/">Home</a></li>
        <li><a href="services.html">What We Do</a></li>
        <li><a href="conditions.html">Conditions We Support</a></li>
        <li><a href="approach.html">Our Method</a></li>
        <li><a href="pricing.html">Investment</a></li>
        <li><a href="about.html">Meet</a></li>
        <li><a href="book.html">Book</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- Hero (hero) -->
    <section class="hero" id="hero">
      <div class="hero-left">
        <h1>Whole-person care that meets you where you are.</h1>
        <p class="lead">At {{BUSINESS_NAME}}, we blend modern testing, herbal & nutritional guidance, movement and meaningful lifestyle shifts to support resilience — not quick fixes.</p>
        <div class="hero-cta">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="book.html">Schedule a consult</a>
        </div>
        <ul class="hero-features">
          <li>Personalized intake & follow-ups</li>
          <li>Optional labs explained clearly</li>
          <li>Plans for body, mind & rhythms</li>
        </ul>
      </div>
      <aside class="hero-right" role="presentation">
        <div class="pattern-wrap">
          <img src="assets/img/pattern.svg" alt="decorative background pattern">
        </div>
        <div class="contact-pill">
          <strong>{{PRACTITIONER_NAME}}, {{CREDENTIALS}}</strong>
          <span>Call to chat: <a href="tel:{{PHONE}}">{{PHONE}}</a></span>
        </div>
      </aside>
    </section>

    <!-- Social Proof (social_proof) -->
    <section class="social-proof" aria-label="Testimonials">
      <h2>Kind words from clients</h2>
      <div class="testimonials">
        <blockquote>
          "A thoughtful, science-forward approach that finally helped me sleep better. No hype — just listening and a plan."<cite>— A.S., Portland</cite>
        </blockquote>
        <blockquote>
          "I appreciated the education. We ran targeted labs and built habits that fit my life."<cite>— R.M., Remote</cite>
        </blockquote>
        <blockquote>
          "Gentle, rigorous, and practical. The follow-ups kept me on track."<cite>— K.L., Local</cite>
        </blockquote>
      </div>
    </section>

    <!-- Benefits (benefits) -->
    <section class="benefits">
      <h2>How we help</h2>
      <p class="muted">Holistic steps with measurable outcomes — education first, partnership always.</p>
      <div class="benefit-grid">
        <div class="card">
          <h3>Personalized Nutrition</h3>
          <p>Food as a foundation: targeted meal patterns and practical swaps tailored to your rhythms.</p>
        </div>
        <div class="card">
          <h3>Stress & Sleep Support</h3>
          <p>Tools to calm the nervous system and rebuild restorative sleep without promises of cures.</p>
        </div>
        <div class="card">
          <h3>Gut & Inflammation Care</h3>
          <p>Digestive resilience strategies plus explanation of when testing could be helpful.</p>
        </div>
        <div class="card">
          <h3>Energy & Hormone Balance</h3>
          <p>Actionable pacing, rhythms, and labs when appropriate to inform a safer plan.</p>
        </div>
      </div>
    </section>

    <!-- Process (process) -->
    <section class="process">
      <h2>What working together looks like</h2>
      <ol>
        <li><strong>Intake & Listening:</strong> A detailed intake to understand history, goals, and context.</li>
        <li><strong>Evidence-based Plan:</strong> Nutrition, movement, stress tools, and optional labs explained.
        </li>
        <li><strong>Implementation:</strong> Gradual habit-building with practical check-ins and resources.</li>
        <li><strong>Follow-up & Adjust:</strong> Regular reviews to refine the plan; labs only if useful for clarity.</li>
      </ol>
      <p class="disclaimer">We emphasize education and supportive care. We do not promise cures — outcomes depend on many factors and individual variability.</p>
    </section>

    <!-- FAQ (faq) -->
    <section class="faq">
      <h2>Common questions</h2>
      <details>
        <summary>Do you use lab testing?</summary>
        <div class="answer">Sometimes. We recommend labs when the results will change care. We explain the pros, cons, and alternatives clearly.</div>
      </details>
      <details>
        <summary>Will I get a one-size-fits-all plan?</summary>
        <div class="answer">No. Plans are individualized for your schedule, preferences, and health history.</div>
      </details>
      <details>
        <summary>Is this a replacement for my physician?</summary>
        <div class="answer">We partner with your existing medical team when needed and refer back for urgent or complex issues.</div>
      </details>
    </section>

    <!-- Lead Magnet (lead_magnet) -->
    <section class="lead-magnet" aria-label="Free guide">
      <div class="lead-inner">
        <h2>Free guide: 7 Holistic Habits to Start This Month</h2>
        <p>Small, sustainable steps to begin rebuilding energy, digestion, and sleep. Delivered as a PDF and a short email course.</p>
        <form id="lead-form">
          <label for="lead-email">Email</label>
          <input id="lead-email" name="email" type="email" placeholder="you@domain.com" required>
          <button type="submit" class="btn primary">Send me the guide</button>
          <p class="privacy">We respect your inbox. No selling, unsubscribe anytime.</p>
        </form>
      </div>
    </section>

    <!-- CTA (cta) -->
    <section class="final-cta">
      <div>
        <h2>Ready for a science-forward, whole-person plan?</h2>
        <p>Start with a single intake visit or choose an intensive bundle for deeper support.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="contact-line">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <small>© {{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • Licensed practice. Not a substitute for medical care.</small>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
