{"path":"assets/css/styles.css","content":"/* Playful premium split-diagonal layout */
:root{
  --bg:#0f1724;
  --accent:#8ee7d3;
  --accent-deep:#4bd6b0;
  --muted:#9aa4b2;
  --card:#ffffff0f;
  --glass:#ffffff08;
  --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef3;background:linear-gradient(180deg,#071025 0%, #081426 60%);}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;position:sticky;top:0;backdrop-filter: blur(6px);z-index:20}
.brand .logo{font-weight:700;color:var(--accent);text-decoration:none;font-size:20px}
.brand .tag{display:block;color:var(--muted);font-size:12px}
.main-nav{position:relative}
#nav-toggle{display:none;background:none;border:0;color:var(--muted);font-size:20px}
#nav-list{display:flex;gap:14px;list-style:none;margin:0;padding:0}
#nav-list a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:10px}
#nav-list a:hover{background:linear-gradient(90deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));color:var(--accent)}
/* Hero split diagonal */
.split-diagonal main{position:relative}
.hero{display:grid;grid-template-columns:1fr 460px;gap:36px;align-items:stretch;padding:48px;position:relative;overflow:visible}
.hero::before{content:'';position:absolute;right:40px;top:0;bottom:0;width:60%;background:linear-gradient(180deg, rgba(74,204,172,0.06), transparent 40%);transform:skewX(-12deg);border-radius:40px;z-index:0}
.hero-left{position:relative;z-index:2;color:#f7feff}
.hero-left h1{font-size:38px;margin:0 0 12px;line-height:1.05}
.hero-left .lead{color:var(--muted);margin-bottom:18px}
.btn{display:inline-block;padding:12px 18px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-deep));color:#03211b;box-shadow:0 6px 18px rgba(75,214,176,0.12)}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);margin-left:10px}
.hero-features{display:flex;gap:10px;margin-top:20px;color:var(--muted);list-style:none;padding:0}
.hero-right{position:relative;z-index:1;display:flex;align-items:center;justify-content:center}
.pattern-wrap{width:100%;height:100%;display:flex;align-items:center;justify-content:center}
.pattern-wrap img{width:100%;max-width:420px;opacity:0.95}
.contact-pill{position:absolute;left:36px;bottom:28px;background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.018));padding:12px 14px;border-radius:12px;color:var(--muted);backdrop-filter: blur(6px);box-shadow:0 6px 30px rgba(0,0,0,0.45)}
.contact-pill strong{color:var(--accent);display:block}

.social-proof{padding:36px 48px;background:linear-gradient(180deg, rgba(255,255,255,0.01), transparent);margin-top:10px;border-top:1px solid rgba(255,255,255,0.02)}
.social-proof h2{color:var(--accent);margin:0 0 12px}
.testimonials{display:flex;gap:14px}
.testimonials blockquote{background:var(--card);padding:16px;border-radius:12px;color:var(--muted);font-style:italic;margin:0}
.testimonials cite{display:block;margin-top:8px;font-style:normal;color:#8fb9a9;font-weight:600}

.benefits{padding:42px 48px}
.benefits h2{color:#d9fff3}
.benefit-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:16px}
.card{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:18px;border-radius:12px;color:var(--muted)}

.process{padding:36px 48px;background:linear-gradient(0deg, rgba(11,18,28,0.2), transparent)}
.process h2{color:var(--accent)}
.process ol{color:var(--muted);padding-left:18px}
.process .disclaimer{color:#bfbfbf;font-size:13px;margin-top:12px}

.faq{padding:24px 48px}
.faq details{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;margin-bottom:10px}
.faq summary{cursor:pointer;color:var(--accent)}
.faq .answer{color:var(--muted);margin-top:8px}

.lead-magnet{display:flex;justify-content:center;padding:40px 20px;background:linear-gradient(90deg, rgba(142,231,211,0.04), rgba(75,214,176,0.02))}
.lead-inner{max-width:720px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:20px;border-radius:12px}
.lead-inner form{display:flex;gap:10px;align-items:center}
#lead-email{flex:1;padding:10px;border-radius:10px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eaf6f0}
.privacy{font-size:12px;color:var(--muted);margin-top:8px}

.final-cta{padding:48px;text-align:center;background:linear-gradient(180deg, rgba(3,33,27,0.3), transparent)}
.final-cta h2{color:var(--accent)}
.final-cta p{color:var(--muted)}
.btn.large{padding:14px 26px;font-size:16px}
.contact-line{color:var(--muted);margin-top:10px}

.site-footer{padding:18px;text-align:center;color:var(--muted);font-size:13px}

/* Responsive */
@media (max-width:900px){
  .hero{grid-template-columns:1fr;gap:16px;padding:28px}
  .pattern-wrap img{max-width:320px}
  #nav-toggle{display:inline-block}
  #nav-list{display:none;position:absolute;right:10px;top:44px;flex-direction:column;background:#05101a;padding:12px;border-radius:10px}
  #nav-list.show{display:flex}
  .testimonials{flex-direction:column}
  .benefit-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactivity: nav toggle, smooth scroll, lead form
document.addEventListener('DOMContentLoaded',function(){
  var toggle=document.getElementById('nav-toggle');
  var list=document.getElementById('nav-list');
  if(toggle){toggle.addEventListener('click',function(){
    var expanded = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', !expanded);
    list.classList.toggle('show');
  });}

  // Smooth scrolling for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id = this.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el) el.scrollIntoView({behavior:'smooth'});
    });
  });

  // Lead magnet form - simulate subscribe and show thanks
  var leadForm = document.getElementById('lead-form');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email = document.getElementById('lead-email').value;
      if(!email) return;
      // rudimentary localStorage to remember
      try{ localStorage.setItem('lead_email', email); }catch(e){}
      leadForm.innerHTML = '<p style="color:#dffbf0;font-weight:600">Thanks! Check your inbox for the guide. <small style="display:block;color:#9ad9c6;margin-top:6px">We respect your privacy.</small></p>';
    });
  }
});"} 
